function cleanText(value,fallback=""){return typeof value==="string"?value.trim().slice(0,1000):fallback}
function cleanNumber(value,max=100){if(value===null||value===undefined||value==="")return null;let n=Number(value);return Number.isFinite(n)&&n>=0&&n<=max?n:null}
