function save(s="Saved",countChange=true){data.version=VERSION;data.updatedAt=new Date().toISOString();if(countChange)data.changesSinceBackup=(Number(data.changesSinceBackup)||0)+1;normalizeOrigins(data);try{localStorage.setItem(KEY,JSON.stringify(data))}catch(e){console.warn(e);render();toast("Save failed — storage full or blocked");return}render();updateLocalStatus();toast(s)}const tagset=a=>(a||[]).slice(0,4).map(x=>`<i class="tag">${esc(x)}</i>`).join(" "),empty=(a,b)=>`<div class="empty"><b>${esc(a)}</b><span>${esc(b)}</span></div>`,safeUrl=u=>/^https?:\/\//i.test(String(u||"").trim())?String(u).trim():"";
const views={dashboard:["MISSION // 01","DASHBOARD"],timeline:["MISSION // 02","TIMELINE"],budget:["MISSION // 03","BUDGET"],bookings:["MISSION // 04","BOOKINGS"],itinerary:["MISSION // 05","ITINERARY"],research:["MISSION // 06","RESEARCH"],social:["MISSION // 07","SOCIAL FINDS"],places:["MISSION // 08","PLACES"],ops:["MISSION // 09","TRAVEL OPS"],logistics:["MISSION // 10","LOGISTICS"],packing:["MISSION // 11","PACKING"],tips:["MISSION // 12","TIPS"]};
