function deadlineState(x){if(x.completed)return"completed";let today=new Date();today.setHours(0,0,0,0);let due=new Date(x.dueDate+"T00:00:00"),days=Math.ceil((due-today)/864e5);return days<0?"overdue":days<=30?"upcoming":"scheduled"}
function dashboard(){let days=Math.max(0,Math.ceil((new Date("2028-03-14T00:00:00")-new Date())/864e5)),goal=data.expenses.reduce((n,x)=>n+Number(x.estimated||0),0)||1;$("#countdown").textContent=days.toLocaleString();$("#savedAmount").textContent="$"+data.savedAmount.toLocaleString(undefined,{maximumFractionDigits:2});$("#fundBar").style.width=Math.min(100,data.savedAmount/goal*100)+"%";$("#statPlaces").textContent=data.places.length;$("#statUnverified").textContent=data.research.filter(x=>!x.verified).length+data.socialFinds.length;$("#inboxBadge").textContent=data.research.filter(x=>x.status==="Inbox").length;$("#socialBadge").textContent=data.socialFinds.length;let up=data.deadlines.filter(x=>!x.completed).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,4);$("#deadlineQueue").innerHTML=up.length?up.map(x=>`<div class="queue-item"><i class="${deadlineState(x)}"></i><div><b>${esc(x.title)}</b><small>${esc(formatDate(x.dueDate))} · ${esc(x.notes)}</small></div><span class="tag">${deadlineState(x)}</span></div>`).join(""):empty("Timeline complete","Every deadline is marked done.")}
function parseDate(s){let y=(s.match(/20\d\d/)||["2028"])[0],months={january:0,february:1,march:2,april:3,may:4,june:5,july:6,august:7,september:8,october:9,november:10,december:11},m=Object.keys(months).find(k=>s.toLowerCase().includes(k));return new Date(+y,m?months[m]:11,1)}
function timelineView(){let states=data.deadlines.map(deadlineState),filtered=data.deadlines.filter(x=>deadlineFilter==="all"||deadlineState(x)===deadlineFilter).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));$("#deadlineOpen").textContent=data.deadlines.filter(x=>!x.completed).length;$("#deadlineUpcoming").textContent=states.filter(x=>x==="upcoming").length;$("#deadlineOverdue").textContent=states.filter(x=>x==="overdue").length;$("#timelineList").innerHTML=filtered.length?filtered.map((x,i)=>{let state=deadlineState(x),display=x.currency==="JPY"?yen(x.cost):money(x.cost),converted=x.currency==="JPY"&&x.cost?`≈ ${money(costUsd(x))}`:"";return `<article class="milestone deadline ${state}"><label class="deadline-check"><input type="checkbox" data-deadline-toggle="${x.id}" ${x.completed?"checked":""}><span>✓</span></label><div><div class="record-tags">${tagset([x.category,state])}</div><h3>${esc(x.title)}</h3><p>${esc(x.notes||"No notes.")}</p></div><div class="when"><b>${esc(formatDate(x.dueDate))}</b><span>${display}${converted?` · ${converted}`:""}</span><div class="mini-actions"><button data-edit-deadline="${x.id}">EDIT</button><button data-delete-deadline="${x.id}">DELETE</button></div></div></article>`}).join(""):empty("No deadlines here","Change the filter or add a deadline.")}
function budget(){let estimated=data.expenses.reduce((n,x)=>n+Number(x.estimated||0),0),actual=data.expenses.reduce((n,x)=>n+Number(x.actual||0),0),paid=data.expenses.filter(x=>x.paid).reduce((n,x)=>n+Number(x.actual||x.estimated||0),0),remaining=Math.max(0,estimated-data.savedAmount);$("#budgetEstimated").textContent=money(estimated);$("#budgetActual").textContent=money(actual);$("#budgetRemaining").textContent=money(remaining);$("#budgetStatus").textContent=actual>estimated?`${money(actual-estimated)} over estimate`:actual?`${money(estimated-actual)} below estimate`:"Add actual costs as you book";$("#budgetPaid").textContent=`${money(paid)} marked paid`;$("#budgetGoalText").textContent=`${money(data.savedAmount)} saved of ${money(estimated)}`;$("#expenseList").innerHTML=data.expenses.length?data.expenses.map(x=>`<article class="expense-item ${x.paid?"is-paid":""}"><div><span class="tag">${esc(x.category)}</span><h3>${esc(x.name)}</h3><small>${x.dueDate?`Due ${esc(formatDate(x.dueDate))}`:"No due date"}${x.notes?` · ${esc(x.notes)}`:""}</small></div><div class="expense-cost"><small>ESTIMATED</small><b>${money(x.estimated)}</b><small>ACTUAL</small><strong>${x.actual?money(x.actual):"—"}</strong></div><span class="payment-state">${x.paid?"✓ PAID":"UNPAID"}</span><div class="mini-actions"><button data-edit-expense="${x.id}">EDIT</button><button data-delete-expense="${x.id}">DELETE</button></div></article>`).join(""):empty("No expenses yet","Add the first cost for your trip.");let c=0;$("#savingsList").innerHTML=savings.map((x,i)=>{c+=x[1];return `<div class="saving-row"><span class="tag">${i+1}</span><div><b>${x[0]} · ${esc(x[2])}</b><small>Cumulative ${money(c)}</small></div><strong>${money(x[1])}</strong></div>`}).join("");$("#savedInput").value=data.savedAmount;$("#savedInput").max=estimated||999999}
const money=n=>Number(n||0).toLocaleString(undefined,{style:"currency",currency:"USD",maximumFractionDigits:2}),formatDate=s=>{let d=new Date(s+"T00:00:00");return Number.isNaN(d.getTime())?s:d.toLocaleDateString(undefined,{year:"numeric",month:"short",day:"numeric"})};
const yen=n=>"¥"+Math.round(Number(n||0)).toLocaleString(),costUsd=x=>x.currency==="JPY"?Number(x.cost||0)/data.yenPerUsd:Number(x.cost||0),periodOrder={Morning:1,Afternoon:2,Evening:3};
function itineraryView(){let total=data.itinerary.reduce((n,x)=>n+costUsd(x),0);$("#yenRate").value=data.yenPerUsd;$("#itineraryTotal").textContent=money(total);$("#itineraryCount").textContent=data.itinerary.length+" planned activit"+(data.itinerary.length===1?"y":"ies");$("#itineraryDays").innerHTML=tripDays.map((date,i)=>{let items=data.itinerary.filter(x=>x.date===date).sort((a,b)=>(periodOrder[a.period]||9)-(periodOrder[b.period]||9)||String(a.reservationTime).localeCompare(String(b.reservationTime))),dayTotal=items.reduce((n,x)=>n+costUsd(x),0),city=items.find(x=>x.city)?.city||dayCity(date);return `<article class="day-card"><header class="day-head"><div><small>DAY ${String(i+1).padStart(2,"0")} · ${esc(city)}</small><h2>${esc(new Date(date+"T00:00:00").toLocaleDateString(undefined,{weekday:"long",month:"short",day:"numeric"}))}</h2></div><div><strong>${money(dayTotal)}</strong><button data-add-itinerary="${date}">＋ ADD PLAN</button></div></header><div class="day-plans">${items.length?items.map(x=>`<div class="plan-item ${x.flexibility==="Fixed"?"fixed":"flexible"}"><div class="plan-time"><span>${esc(x.period)}</span><b>${x.reservationTime?esc(x.reservationTime):"OPEN"}</b></div><div class="plan-main"><div>${tagset([x.flexibility,x.city,x.neighborhood].filter(Boolean))}</div><h3>${esc(x.title)}</h3>${x.address?`<p>${safeUrl(x.mapUrl)?`<a href="${esc(safeUrl(x.mapUrl))}" target="_blank" rel="noopener noreferrer">${esc(x.address)} ↗</a>`:esc(x.address)}</p>`:""}${x.transit?`<small>TRANSIT // ${esc(x.transit)}</small>`:""}${x.confirmation?`<small>CONFIRMATION // ${esc(x.confirmation)}</small>`:""}</div><div class="plan-cost"><b>${x.currency==="JPY"?yen(x.cost):money(x.cost)}</b>${x.currency==="JPY"?`<small>≈ ${money(costUsd(x))}</small>`:""}</div><div class="mini-actions"><button data-edit-itinerary="${x.id}">EDIT</button><button data-delete-itinerary="${x.id}">DELETE</button></div></div>`).join(""):empty("Day is open","Add a morning, afternoon, or evening plan.")}</div></article>`}).join("")}
function cancellationState(x){if(!x.cancellationDeadline||x.status==="Cancelled")return"none";let today=new Date();today.setHours(0,0,0,0);let d=new Date(x.cancellationDeadline+"T00:00:00"),days=Math.ceil((d-today)/864e5);return days<0?"expired":days<=30?"soon":"active"}
function bookingsView(){let active=data.bookings.filter(x=>x.status!=="Cancelled"),reserved=active.filter(x=>["Reserved","Paid"].includes(x.status)).length,total=active.reduce((n,x)=>n+costUsd(x),0),warnings=data.bookings.filter(x=>["soon","expired"].includes(cancellationState(x))).length,filtered=data.bookings.filter(x=>bookingFilter==="all"||x.type===bookingFilter).sort((a,b)=>String(a.travelDate).localeCompare(String(b.travelDate)));$("#bookingReserved").textContent=reserved+" / "+active.length;$("#bookingTotal").textContent=money(total);$("#bookingWarnings").textContent=warnings;$("#bookingList").innerHTML=filtered.length?filtered.map(x=>{let cancel=cancellationState(x),display=x.currency==="JPY"?yen(x.price):money(x.price);return `<article class="booking-card status-${x.status.toLowerCase()} cancel-${cancel}"><div class="booking-top"><div>${tagset([x.type,x.status])}<h3>${safeUrl(x.url)?`<a href="${esc(safeUrl(x.url))}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a>`:esc(x.title)}</h3><p>${esc(x.provider||"Provider TBD")}</p></div><div class="booking-price"><strong>${display}</strong>${x.currency==="JPY"?`<small>≈ ${money(costUsd(x))}</small>`:""}</div></div><div class="booking-meta"><span>TRAVEL<br><b>${x.travelDate?esc(formatDate(x.travelDate)):"TBD"}</b></span><span>BOOKED<br><b>${x.bookingDate?esc(formatDate(x.bookingDate)):"NOT YET"}</b></span><span>CANCEL BY<br><b>${x.cancellationDeadline?esc(formatDate(x.cancellationDeadline)):"NO DATE"}</b></span><span>CONFIRMATION<br><b>${esc(x.confirmation||"—")}</b></span></div>${cancel!=="none"?`<div class="cancel-alert ${cancel}">${cancel==="expired"?"! CANCELLATION DEADLINE PASSED":"! CANCELLATION DEADLINE WITHIN 30 DAYS"}</div>`:""}${x.notes?`<p class="booking-notes">${esc(x.notes)}</p>`:""}<div class="mini-actions"><button data-edit-booking="${x.id}">EDIT</button><button data-delete-booking="${x.id}">DELETE</button></div></article>`}).join(""):empty("No bookings here","Change the filter or add a booking.")}
function research(){let q=$("#researchSearch").value.toLowerCase(),s=$("#statusFilter").value,c=$("#cityFilter").value,cs=[...new Set(data.research.flatMap(x=>locationFromLegacy(x).cities).concat(data.research.flatMap(x=>locationFromLegacy(x).otherLocations?[locationFromLegacy(x).otherLocations]:[])).filter(Boolean))].sort();$("#cityFilter").innerHTML='<option value="all">All cities</option>'+cs.map(x=>`<option>${esc(x)}</option>`).join("");if(cs.includes(c))$("#cityFilter").value=c;let a=data.research.filter(x=>[x.title,locationLabel(x),neighborhoodLabel(x),x.category,x.type,x.notes,...(x.tags||[])].join(" ").toLowerCase().includes(q)&&(s==="all"||x.status===s)&&(c==="all"||locationLabel(x).includes(c))&&(!unverifiedOnly||!x.verified));$("#researchList").innerHTML=a.length?a.map(x=>`<article class="record priority-${x.priority.toLowerCase()}"><div class="stripe"></div><div class="record-body"><div class="record-tags">${tagset([x.type,x.category,x.status])}</div><h3>${safeUrl(x.url)?`<a href="${esc(safeUrl(x.url))}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a>`:esc(x.title)}</h3><p>${esc(x.notes||"No notes yet.")}</p><div class="meta"><span>${esc(locationLabel(x))}${neighborhoodLabel(x)?` · ${esc(neighborhoodLabel(x))}`:""}</span><span>${x.priority}</span><span class="${x.verified?"yes":"no"}">${x.verified?"✓ Verified":"! Unverified"}</span></div></div><div class="card-actions"><button class="icon" title="Promote" data-promote-record="${x.id}">＋</button><button class="icon" data-edit-record="${x.id}">✎</button><button class="icon" data-delete-record="${x.id}">×</button></div></article>`).join(""):empty("Inbox ready","Add research whenever you find it.")}
function social(){let q=$("#socialSearch").value.toLowerCase(),c=$("#socialCity").value,a=data.socialFinds.filter(x=>[x.name,locationLabel(x),neighborhoodLabel(x),x.category,x.order,x.priority].join(" ").toLowerCase().includes(q)&&(c==="all"||locationLabel(x).includes(c)));$("#socialList").innerHTML=a.length?a.map(x=>`<article class="social-card"><div>${tagset([locationLabel(x),x.category,x.priority])}</div><h3>${esc(x.name)}</h3><p><b>${esc(neighborhoodLabel(x)||"Neighborhood TBD")}</b><br>${esc(x.order||"No key order/tip yet.")}</p>${safeUrl(x.url)?`<a href="${esc(safeUrl(x.url))}" target="_blank" rel="noopener noreferrer">OPEN TIKTOK / INSTAGRAM ↗</a>`:""}<div class="mini-actions"><button data-promote-social="${x.id}">VERIFY + PROMOTE</button><button data-edit-social="${x.id}">EDIT</button><button data-delete-social="${x.id}">DELETE</button></div></article>`).join(""):empty("Social inbox empty","The next TikTok or Instagram find goes here.")}
function places(){let q=$("#placeSearch").value.toLowerCase(),c=$("#placeCity").value,a=data.places.filter(x=>[x.name,locationLabel(x),x.category,neighborhoodLabel(x),x.notes,...(x.tags||[])].join(" ").toLowerCase().includes(q)&&(c==="all"||locationLabel(x).includes(c)));$("#placesGrid").innerHTML=a.length?a.map((x,i)=>`<article class="place"><strong>${String(i+1).padStart(2,"0")}</strong><div><small>${esc(locationLabel(x))} // ${esc(x.category)}</small><h3>${esc(x.name)}</h3><p><b>${esc(neighborhoodLabel(x)||"")}</b><br>${esc(x.notes||"")}</p>${tagset(x.tags)}<div class="mini-actions"><button data-edit-place="${x.id}">EDIT</button><button data-delete-place="${x.id}">DELETE</button></div></div></article>`).join(""):empty("No places found","Change the search or add a target.")}
function logisticsView(){renderLogisticsTools();$("#lodgingGrid").innerHTML=lodging.map((x,i)=>{let d=data.dining?.[i]||diningDefaults[i];return `<article class="lodge"><span class="night">${x.nights} NIGHT${x.nights>1?"S":""}</span><small>${esc(x.city)} · ${esc(x.dates)}</small><h3>${esc(x.name)}</h3><strong>$${x.cost}</strong><p>${esc(x.note)}</p>${hotelAddressHtml(i)}<div class="dining-details"><h4>FOOD & DINING</h4><p><b>Meal plan:</b> ${esc(d.mealPlan)}</p><p><b>Breakfast:</b> ${esc(d.breakfastPrice)}</p><p><b>Included food:</b> ${esc(d.includedMeals)}</p><p><b>Notes:</b> ${esc(d.notes)}</p><button type="button" data-edit-dining="${i}">EDIT DINING</button></div></article>`}).join("");$("#logisticsList").innerHTML=logistics.map(x=>`<article class="tip"><span class="tag">LOGISTICS</span><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p></article>`).join("")}

