function showHotelAddress(i){let x=data.hotelAddresses[i];$("#addressCardTitle").textContent=lodging[i].name;$("#addressCardBody").innerHTML=`<p class="address-request" lang="ja">ここへ行きたいです。</p><h3 lang="ja">${esc(x.nameJa)}</h3><p lang="ja">${esc(x.addressJa)||"Address not entered"}</p><p>${esc(x.phone)}</p><p class="address-meta">Source checked: ${esc(x.checkedOn)||"Not recorded"}</p>${safeUrl(x.sourceUrl)?`<a href="${esc(safeUrl(x.sourceUrl))}" target="_blank" rel="noopener noreferrer">Official source</a>`:""}<div class="logistics-actions"><button type="button" id="copyHotelAddress" data-index="${i}">COPY ADDRESS</button></div>`;modal("addressCardModal")}
