function renderLogisticsTools(){
$("#transitionList").innerHTML=data.transitions.map(x=>`<article class="panel transition-card"><small>${esc(x.date)}</small><h3>${esc(x.from)} → ${esc(x.to)}</h3><p><b>Checkout:</b> ${esc(x.checkout)||"Confirm with hotel"} · <b>Next check-in / airport target:</b> ${esc(x.checkin)||"To confirm"}</p><p><b>Route:</b> ${esc(x.route)}</p><p><b>Luggage:</b> ${esc(x.luggage)}</p><p><b>Keep with you:</b> ${esc(x.carry)}</p><p>${esc(x.notes)}</p><strong>${x.tasks.filter(t=>t.done).length} / ${x.tasks.length} ready</strong><div class="transition-checks">${x.tasks.map((t,i)=>`<label><input type="checkbox" data-transition-task="${x.id}:${i}" ${t.done?"checked":""}> ${esc(t.title)}</label>`).join("")}</div><button type="button" data-edit-logistics="transition:${x.id}">EDIT TRANSFER</button></article>`).join("");
$("#baggageList").innerHTML=Object.entries(data.baggage).map(([leg,b])=>{let s=baggageSummary(b),messages=[];if(b.allowedCount===null||b.limitKg===null)messages.push("Airline allowance not entered yet.");if(s.overCount)messages.push("Planned bags exceed your recorded allowance.");if(s.overweight)messages.push("A suitcase exceeds your recorded per-bag limit.");if(!s.complete)messages.push("Some suitcase weights still need measuring.");if(b.shoppingKg!==null&&s.remaining!==null&&b.shoppingKg>s.remaining)messages.push("Shopping weight exceeds the remaining combined capacity.");return `<article class="panel baggage-card"><small>${leg==="outbound"?"TO JAPAN":"RETURN TO PORTLAND"}</small><h3>${b.checkedCount} checked suitcase${b.checkedCount===1?"":"s"}</h3><p><b>Carrier / fare:</b> ${esc(b.carrier)||"Not entered"}</p><p><b>Allowance:</b> ${b.allowedCount===null?"Unknown":b.allowedCount+" bags"} · ${b.limitKg===null?"Weight limit unknown":b.limitKg+" kg per bag"}</p><p><b>Measured weights:</b> ${b.weights.slice(0,b.checkedCount).map((w,i)=>"Bag "+(i+1)+": "+(w===null?"not measured":w+" kg")).join(" · ")||"No checked bags"}</p><p><b>Shopping reserve:</b> ${b.shoppingKg===null?"Not set":b.shoppingKg+" kg"}${s.remaining!==null?` · ${s.remaining.toFixed(1)} kg combined capacity left`:""}</p><p>${esc(b.notes)}</p>${messages.map(m=>`<p class="baggage-warning">${esc(m)}</p>`).join("")}<small>Limits apply to each suitcase; combined space does not cancel a per-bag excess.</small>${safeUrl(b.allowanceUrl)?`<p><a href="${esc(safeUrl(b.allowanceUrl))}" target="_blank" rel="noopener noreferrer">Airline allowance source</a></p>`:""}<div class="logistics-actions"><button type="button" data-edit-logistics="baggage:${leg}">EDIT BAGGAGE</button></div></article>`}).join("")}
function openLogisticsEditor(kind,id){let x,fields;if(kind==="address"){x=data.hotelAddresses[Number(id)];fields=[["nameJa","Japanese hotel name"],["addressJa","Japanese address","textarea"],["phone","Hotel phone"],["sourceUrl","Official source URL","url"],["checkedOn","Source checked on","date"]]}else if(kind==="transition"){x=data.transitions.find(v=>v.id===id);fields=[["date","Transfer date","date"],["from","From"],["to","To"],["checkout","Checkout time","time"],["checkin","Next check-in / airport target","time"],["route","Route notes","textarea"],["luggage","Luggage handoff / collection","textarea"],["carry","Keep with you","textarea"],["notes","Additional notes","textarea"]]}else {x=data.baggage[id];fields=[["carrier","Airline / fare"],["checkedCount","Planned checked bags (0–2)","number",2,1],["allowedCount","Purchased / included checked bags","number",10,1],["limitKg","Per-bag weight limit (kg)","number",100,.1],["weight0","First suitcase weight (kg)","number",100,.1],["weight1","Second suitcase weight (kg)","number",100,.1],["shoppingKg","Weight to reserve for shopping (kg)","number",100,.1],["allowanceUrl","Airline allowance URL","url"],["notes","Packing strategy","textarea"]];x={...x,weight0:x.weights[0],weight1:x.weights[1]}}if(!x)return;$("#logisticsKind").value=kind;$("#logisticsId").value=id;$("#logisticsModalTitle").textContent=kind==="address"?"Edit hotel address":kind==="transition"?"Edit hotel transfer":"Edit "+id+" baggage";$("#logisticsFields").innerHTML=fields.map(([key,label,type="text",max,step])=>`<label class="${type==="textarea"?"wide":""}">${esc(label)}${type==="textarea"?`<textarea name="${key}" maxlength="1000" rows="3">${esc(x[key])}</textarea>`:`<input name="${key}" type="${type}" value="${esc(x[key])}" ${type==="number"?`min="0" max="${max}" step="${step}"`:"maxlength=1000"} ${key==="checkedCount"?"required":""}>`}</label>`).join("");modal("logisticsModal")}
document.addEventListener("click",e=>{let b=e.target.closest("button");if(!b)return;if(b.dataset.showAddress!==undefined)showHotelAddress(Number(b.dataset.showAddress));if(b.id==="copyHotelAddress")copyHotelAddress(Number(b.dataset.index));if(b.dataset.editLogistics){let [kind,id]=b.dataset.editLogistics.split(":");openLogisticsEditor(kind,id)}});
document.addEventListener("change",e=>{let key=e.target.dataset.transitionTask;if(!key)return;let [id,index]=key.split(":"),x=data.transitions.find(v=>v.id===id);if(x?.tasks[index]){x.tasks[index].done=e.target.checked;save("Transfer checklist saved");$(`[data-transition-task="${key}"]`)?.focus()}});
$("#logisticsForm").onsubmit=e=>{e.preventDefault();let kind=$("#logisticsKind").value,id=$("#logisticsId").value,values=Object.fromEntries(new FormData(e.target));if(kind==="address"){data.hotelAddresses[Number(id)]={...data.hotelAddresses[Number(id)],...values};data.hotelAddresses=sanitizeAddresses(data.hotelAddresses)}else if(kind==="transition"){let index=data.transitions.findIndex(x=>x.id===id);data.transitions[index]={...data.transitions[index],...values};data.transitions=sanitizeTransitions(data.transitions)}else{data.baggage[id]={...values,checkedCount:Number(values.checkedCount),weights:[values.weight0,values.weight1]};data.baggage=sanitizeBaggage(data.baggage)}modal("logisticsModal",false);save("Logistics saved")};

function editDining(i){const d=data.dining[i]||diningDefaults[i],next={...d};for(const [key,label] of [["mealPlan","Meal plan"],["breakfastPrice","Breakfast price / inclusion"],["includedMeals","Included food and snacks"],["notes","Dining notes"]]){const value=prompt(label,next[key]||"");if(value===null)return;next[key]=value.trim().slice(0,500)}data.dining[i]=next;save("Dining details saved")}
function packingView(){let q=$("#packingSearch").value.toLowerCase(),c=$("#packingCategory").value,bag=$("#packingBag").value,cats=[...new Set(data.packingItems.map(x=>x.category))].sort(),packed=data.packingItems.filter(x=>x.packed).length,total=data.packingItems.length,pct=total?Math.round(packed/total*100):0;$("#packingCategory").innerHTML='<option value="all">All categories</option>'+cats.map(x=>`<option>${esc(x)}</option>`).join("");if(cats.includes(c))$("#packingCategory").value=c;$("#packedCount").textContent=`${packed} / ${total}`;$("#packedPercent").textContent=pct+"%";$("#packedBar").style.width=pct+"%";$("#buyJapanCount").textContent=data.packingItems.filter(x=>x.buyInJapan).length;$("#packingWarningCount").textContent=data.packingItems.filter(x=>x.warning&&!x.packed).length;let a=data.packingItems.filter(x=>[x.name,x.category,x.bag,x.details,x.notes,x.warningText].join(" ").toLowerCase().includes(q)&&(c==="all"||x.category===c)&&(bag==="all"||x.bag===bag));$("#packingList").innerHTML=a.length?a.map(x=>`<article class="pack-item ${x.packed?"packed":""} ${x.warning?"has-warning":""}"><label class="pack-check"><input type="checkbox" data-pack-toggle="${x.id}" ${x.packed?"checked":""}><span>✓</span></label><div class="pack-main"><div>${tagset([x.category,x.bag,x.buyInJapan?"Buy in Japan":"Pack from home"])}</div><h3>${esc(x.name)} <small>× ${x.quantity}</small></h3><p>${esc(x.details||"")}${x.notes?`<br>${esc(x.notes)}`:""}</p>${x.warning?`<div class="pack-warning">! ${esc(x.warningText||"Medication or document item—verify before departure.")}</div>`:""}</div><div class="mini-actions"><button data-edit-pack="${x.id}">EDIT</button><button data-delete-pack="${x.id}">DELETE</button></div></article>`).join(""):empty("No packing items found","Change the filters or add an item.")}
function operationsView(){$$(".ops-panel").forEach(x=>x.hidden=x.dataset.opsPanel!==opsPanel);$$('[data-ops-tab]').forEach(x=>x.classList.toggle("active",x.dataset.opsTab===opsPanel));$("#transitList").innerHTML=data.transitPasses.map(x=>`<article class="ops-card"><div>${tagset([x.type,x.status])}</div><h3>${esc(x.name)}</h3><p><b>${esc(x.coverage)}</b><br>${esc(x.bestFor)}</p><strong>${x.currency==="JPY"?yen(x.cost):money(x.cost)}</strong>${x.currency==="JPY"&&x.cost?`<small>≈ ${money(costUsd(x))}</small>`:""}<p>${esc(x.validity)}${x.notes?` · ${esc(x.notes)}`:""}</p><div class="mini-actions"><button data-edit-ops="transit:${x.id}">EDIT</button><button data-delete-ops="transit:${x.id}">DELETE</button></div></article>`).join("")||empty("No transit options","Add an IC card, ticket, or pass comparison.");let done=data.compliance.filter(x=>x.completed).length;$("#complianceProgress").textContent=`${done} / ${data.compliance.length} complete`;$("#complianceList").innerHTML=data.compliance.map(x=>`<article class="checklist-row ${x.completed?"done":""} ${x.warning?"warning":""}"><label><input type="checkbox" data-compliance-toggle="${x.id}" ${x.completed?"checked":""}><span>✓</span></label><div>${tagset([x.category])}<h3>${esc(x.title)}</h3><p>${x.dueDate?`Due ${esc(formatDate(x.dueDate))} · `:""}${esc(x.notes)}</p></div><div class="mini-actions"><button data-edit-ops="compliance:${x.id}">EDIT</button><button data-delete-ops="compliance:${x.id}">DELETE</button></div></article>`).join("")||empty("Checklist empty","Add a medication, health, or customs task.");$("#documentList").innerHTML=data.documents.map(x=>`<article class="document-row"><div>${tagset([x.status])}<h3>${esc(x.name)}</h3><p>LOCATION // ${esc(x.location||"Not assigned")}${x.expiry?` · EXPIRES // ${esc(formatDate(x.expiry))}`:""}<br>${esc(x.notes)}</p></div><div class="mini-actions"><button data-edit-ops="document:${x.id}">EDIT</button><button data-delete-ops="document:${x.id}">DELETE</button></div></article>`).join("")||empty("No document references","Store locations, never sensitive scans.");$("#careList").innerHTML=data.carePlans.map(x=>`<article class="care-row"><div><small>${esc(formatDate(x.date))} · ${esc(x.city)}</small><h3>${esc(x.weather||"Forecast not added")}</h3><p>${esc(x.temperature||"Temperature TBD")}${x.rain?" · Rain plan needed":""}${x.laundry?" · LAUNDRY DAY":""}<br>${esc(x.notes)}</p></div><button data-edit-ops="care:${x.id}">EDIT</button></article>`).join("");let e=data.emergency;[["emEmbassyAddress",e.embassyAddress],["emEmbassyPhone",e.embassyPhone],["emInsuranceProvider",e.insuranceProvider],["emInsurancePhone",e.insurancePhone],["emAllergies",e.allergies],["emMedications",e.medications],["emContacts",e.contacts],["emNotes",e.notes]].forEach(([id,v])=>$("#"+id).value=v||"")}
function tipsView(){let q=$("#tipSearch").value.toLowerCase(),a=data.tips.filter(x=>[x.title,x.category,x.content,...(x.tags||[])].join(" ").toLowerCase().includes(q));$("#tipsGrid").innerHTML=a.length?a.map(x=>`<article class="tip"><span class="tag">${esc(x.category)}</span><h3>${esc(x.title)}</h3><p>${esc(x.content)}</p>${tagset(x.tags)}<div class="mini-actions"><button data-edit-tip="${x.id}">EDIT</button><button data-delete-tip="${x.id}">DELETE</button></div></article>`).join(""):empty("No tips saved","Add what future-you should remember.")}
