function modal(id,on=true){let box=$("#"+id);if(on){lastFocus=document.activeElement;box.hidden=false;document.body.style.overflow="hidden";requestAnimationFrame(()=>box.querySelector("input:not([type=hidden]),select,textarea,button")?.focus())}else{box.hidden=true;document.body.style.overflow="";lastFocus?.focus?.()}}
function locationFromLegacy(x={}){if(x.locationScope)return{locationScope:x.locationScope,cities:Array.isArray(x.cities)?x.cities:[],neighborhoods:x.neighborhoods&&typeof x.neighborhoods==="object"?x.neighborhoods:{},otherLocations:String(x.otherLocations||""),otherNeighborhood:String(x.otherNeighborhood||"")};let raw=String(x.city||"").trim(),tokens=raw.split(",").map(v=>v.trim()).filter(Boolean),matched=MAIN_CITIES.filter(c=>tokens.some(v=>v.toLowerCase()===c.toLowerCase())),others=tokens.filter(v=>!MAIN_CITIES.some(c=>v.toLowerCase()===c.toLowerCase())),other=others.join(", "),multiple=matched.length+others.length>1;return{locationScope:multiple?"multiple":matched.length===1?"one":other?"other":"nationwide",cities:matched,neighborhoods:matched.length===1&&x.neighborhood?{[matched[0]]:[String(x.neighborhood)]}:{},otherLocations:other,otherNeighborhood:""}}
function locationFieldsHtml(prefix,x={}){let l=locationFromLegacy(x),scopes=[["one","One city"],["multiple","Multiple cities"],["other","Other location"],["nationwide","Nationwide / general"]];return `<fieldset class="location-builder wide" data-location-builder="${prefix}"><legend>Location</legend><label>Location scope<select id="${prefix}LocationScope" data-location-scope="${prefix}">${scopes.map(([v,t])=>`<option value="${v}" ${l.locationScope===v?"selected":""}>${t}</option>`).join("")}</select></label><div class="location-options" id="${prefix}LocationOptions"></div></fieldset>`}
function renderLocationOptions(prefix,initial){let scope=$("#"+prefix+"LocationScope")?.value||"one",box=$("#"+prefix+"LocationOptions");if(!box)return;let l=initial||box._locationValue||{cities:[],neighborhoods:{},otherLocations:"",otherNeighborhood:""};box._locationValue=l;if(scope==="nationwide"){box.innerHTML='<p class="location-hint">No city or neighborhood is required for a Japan-wide or general find.</p>';return}if(scope==="other"){box.innerHTML=`<label>City / area *<input id="${prefix}OtherLocations" value="${esc(l.otherLocations||"")}" placeholder="Nara, Kobe, Hakone…"></label><label>Neighborhood / area (optional)<input id="${prefix}OtherNeighborhood" value="${esc(l.otherNeighborhood||"")}" placeholder="Naramachi"></label>`;return}let multiple=scope==="multiple",selected=l.cities?.length?l.cities:(multiple?[]:["Tokyo"]);box.innerHTML=`<div class="city-choices">${MAIN_CITIES.map(c=>`<label class="choice-chip"><input type="${multiple?"checkbox":"radio"}" name="${prefix}Cities" value="${c}" ${selected.includes(c)?"checked":""}> ${c}</label>`).join("")}${multiple?`<label class="choice-chip"><input type="checkbox" name="${prefix}Cities" value="Other" ${l.otherLocations?"checked":""}> Other</label>`:""}</div><div id="${prefix}Neighborhoods"></div>${multiple?`<label id="${prefix}OtherWrap" ${l.otherLocations?"":"hidden"}>Other cities / areas<input id="${prefix}OtherLocations" value="${esc(l.otherLocations||"")}" placeholder="Nara, Kobe, Yokohama…"></label>`:""}`;renderNeighborhoodChoices(prefix,l.neighborhoods||{})}
function renderNeighborhoodChoices(prefix,selected={}){let host=$("#"+prefix+"Neighborhoods");if(!host)return;let cities=$$(`[name="${prefix}Cities"]:checked`).map(x=>x.value).filter(x=>MAIN_CITIES.includes(x));host.innerHTML=cities.map(city=>`<fieldset class="neighborhood-set"><legend>${city} neighborhoods <small>(choose any)</small></legend><div class="neighborhood-choices">${NEIGHBORHOODS[city].map(n=>`<label class="choice-chip"><input type="checkbox" name="${prefix}Neighborhood-${city}" value="${esc(n)}" ${(selected[city]||[]).includes(n)?"checked":""}> ${esc(n)}</label>`).join("")}</div><label>Another ${city} neighborhood<input id="${prefix}Custom-${city}" value="${esc((selected[city]||[]).filter(n=>!NEIGHBORHOODS[city].includes(n)).join(", "))}" placeholder="Type another area"></label></fieldset>`).join("")}
function readLocation(prefix){let scope=$("#"+prefix+"LocationScope")?.value||"nationwide",cities=[],neighborhoods={},otherLocations="",otherNeighborhood="";if(scope==="one"||scope==="multiple"){cities=$$(`[name="${prefix}Cities"]:checked`).map(x=>x.value).filter(x=>MAIN_CITIES.includes(x));cities.forEach(city=>{let chosen=$$(`[name="${prefix}Neighborhood-${city}"]:checked`).map(x=>x.value),custom=String($("#"+prefix+"Custom-"+city)?.value||"").split(",").map(x=>x.trim()).filter(Boolean);neighborhoods[city]=[...new Set([...chosen,...custom])].filter(Boolean)});otherLocations=$("#"+prefix+"OtherLocations")?.value.trim()||""}else if(scope==="other"){otherLocations=$("#"+prefix+"OtherLocations")?.value.trim()||"";otherNeighborhood=$("#"+prefix+"OtherNeighborhood")?.value.trim()||""}return{locationScope:scope,cities,neighborhoods,otherLocations,otherNeighborhood}}
function locationLabel(x){let l=locationFromLegacy(x);if(l.locationScope==="nationwide")return"Nationwide / general";let parts=[...l.cities];if(l.otherLocations)parts.push(l.otherLocations);return parts.join(", ")||"Location TBD"}
function neighborhoodLabel(x){let l=locationFromLegacy(x),parts=[];Object.entries(l.neighborhoods||{}).forEach(([city,areas])=>{if(areas?.length)parts.push(`${city}: ${areas.join(", ")}`)});if(l.otherNeighborhood)parts.push(l.otherNeighborhood);return parts.join(" · ")}
