const norm=v=>String(v||"").trim().toLowerCase().replace(/\s+/g," ");
function isDuplicateResearch(x,ignore=""){return data.research.some(y=>y.id!==ignore&&((x.url&&norm(y.url)===norm(x.url))||(norm(y.title)===norm(x.title)&&norm(y.city)===norm(x.city))))}
function isDuplicatePlace(x,ignore=""){return data.places.some(y=>y.id!==ignore&&norm(y.name)===norm(x.name)&&norm(y.city)===norm(x.city))}
function validateBackup(x,fileSize=0){let errors=[];if(fileSize>5*1024*1024)errors.push("File exceeds the 5 MB safety limit.");if(!x||typeof x!=="object"||Array.isArray(x))return["Backup root must be a JSON object."];let v=x.version??1;if(!Number.isInteger(Number(v))||Number(v)<1||Number(v)>VERSION)errors.push(`Unsupported schema version: ${v}.`);let keys=["hotelAddresses","transitions","dining","research","socialFinds","places","expenses","itinerary","deadlines","bookings","packingItems","transitPasses","compliance","documents","carePlans","tips"];keys.forEach(k=>{if(k in x&&!Array.isArray(x[k]))errors.push(`${k} must be an array.`);if(Array.isArray(x[k])&&x[k].length>10000)errors.push(`${k} has too many records.`)});if(!Array.isArray(x.research)||!Array.isArray(x.places)||!Array.isArray(x.tips))errors.push("Required research, places, and tips collections are missing.");if(x.yenPerUsd!==undefined&&(!Number.isFinite(Number(x.yenPerUsd))||Number(x.yenPerUsd)<=0))errors.push("Exchange rate must be positive.");if(x.baggage!==undefined&&(!x.baggage||typeof x.baggage!=="object"||Array.isArray(x.baggage)))errors.push("baggage must be an object.");return errors}
function migrateDepartureDate(target,sourceVersion){if(sourceVersion>=12)return target;let departure=target.deadlines.find(x=>x.title==="Departure"&&x.dueDate==="2028-03-15");if(departure){departure.dueDate="2028-03-14";departure.notes="Begin outbound travel; carry medication in original bottles in the personal item."}let flight=target.bookings.find(x=>x.title==="Open-jaw international flight"&&x.travelDate==="2028-03-15");if(flight)flight.travelDate="2028-03-14";return target}
function migrateBackup(x){let sourceVersion=Number(x.version)||1,out={...copy(defaults),hotelAddresses:sanitizeAddresses(x.hotelAddresses),transitions:sanitizeTransitions(x.transitions),baggage:sanitizeBaggage(x.baggage),dining:Array.isArray(x.dining)?diningDefaults.map((d,i)=>({...d,...(x.dining[i]&&typeof x.dining[i]==='object'?Object.fromEntries(Object.entries(x.dining[i]).filter(([k,v])=>k in d&&typeof v==='string').map(([k,v])=>[k,v.slice(0,500)])): {})})):copy(diningDefaults),research:sanitizeResearch(x.research),places:sanitizePlaces(x.places),expenses:Array.isArray(x.expenses)?sanitizeExpenses(x.expenses):copy(expenseSeed),itinerary:sanitizeItinerary(x.itinerary),deadlines:Array.isArray(x.deadlines)?sanitizeDeadlines(x.deadlines):copy(deadlineSeed),bookings:Array.isArray(x.bookings)?sanitizeBookings(x.bookings):copy(bookingSeed),packingItems:Array.isArray(x.packingItems)?sanitizePacking(x.packingItems):copy(packingSeed),transitPasses:sanitizeTransit(x.transitPasses),compliance:sanitizeCompliance(x.compliance),documents:sanitizeDocuments(x.documents),carePlans:sanitizeCare(x.carePlans),emergency:sanitizeEmergency(x.emergency),yenPerUsd:Math.max(1,Number(x.yenPerUsd)||150),tips:sanitizeTips(x.tips),socialFinds:sanitizeSocial(x.socialFinds),version:VERSION,savedAmount:Math.max(0,Number(x.savedAmount)||0),lastExportAt:String(x.lastExportAt||x.exportedAt||""),changesSinceBackup:Math.max(0,Number(x.changesSinceBackup)||0),updatedAt:String(x.updatedAt||"")};return normalizeOrigins(migrateDepartureDate(out,sourceVersion))}
function resetSampleData(){if(!confirm("Reset spreadsheet sample data to its original V9 values? Your user-created records will be preserved."))return;Object.entries(seedCollections).forEach(([key,seed])=>{let user=(data[key]||[]).filter(x=>x.origin!=="seed");data[key]=[...user,...copy(seed)]});normalizeOrigins(data);save("Sample data reset")}
$("#exportBtn").onclick=()=>{data.lastExportAt=new Date().toISOString();data.changesSinceBackup=0;data.updatedAt=data.lastExportAt;localStorage.setItem(KEY,JSON.stringify(data));let blob=new Blob([JSON.stringify({...data,version:VERSION,exportedAt:data.lastExportAt},null,2)],{type:"application/json"}),u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download="japan-2028-planner-v13-"+new Date().toISOString().slice(0,10)+".json";a.click();URL.revokeObjectURL(u);updateLocalStatus();toast("Backup exported")};
$("#importBtn").onclick=()=>$("#importInput").click();$("#importInput").onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader;r.onload=()=>{try{let x=JSON.parse(r.result),errors=validateBackup(x,f.size);if(errors.length)throw new Error(errors.join("\n"));if(confirm(`Import schema v${x.version||1} and replace current planner data? This cannot be undone unless you export first.`)){data=migrateBackup(x);save("Backup imported",false)}}catch(err){alert("Backup rejected:\n\n"+(err.message||"Invalid JSON."))}e.target.value=""};r.readAsText(f)};
function mergeSocialPayload(payload,fileSize){if(fileSize>5*1024*1024)throw new Error("Social Finds file exceeds the 5 MB safety limit.");if(!payload||payload.kind!=="japan-2028-social-finds"||!Array.isArray(payload.socialFinds))throw new Error("This is not a Japan 2028 Social Finds package.");if(payload.socialFinds.length>5000)throw new Error("The package contains too many records.");let incoming=sanitizeSocial(payload.socialFinds),existingIds=new Set(data.socialFinds.map(x=>String(x.sourceVideoId||x.id).replace(/^tt/,""))),added=[];for(let x of incoming){let original=payload.socialFinds.find(y=>String(y.id)===String(x.id))||{},videoId=String(original.sourceVideoId||x.id).replace(/^tt/,"");if(existingIds.has(videoId))continue;added.push({...x,id:x.id||uid("s"),origin:"user",sourceVideoId:videoId,reviewStatus:String(original.reviewStatus||"Verify"),confidence:String(original.confidence||"Low")});existingIds.add(videoId)}return added}
$("#mergeSocialBtn").onclick=()=>$("#mergeSocialInput").click();$("#mergeSocialInput").onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader;r.onload=()=>{try{let payload=JSON.parse(r.result),added=mergeSocialPayload(payload,f.size);if(!added.length){toast("No new Social Finds to merge");return}if(confirm(`Merge ${added.length} new Social Finds? Existing planner data and duplicate video IDs will be preserved.`)){data.socialFinds=[...data.socialFinds,...added];save(`${added.length} Social Finds merged`)}}catch(err){alert("Social Finds package rejected:\n\n"+(err.message||"Invalid JSON."))}finally{e.target.value=""}};r.readAsText(f)};
