let mobileDataToggle=$("#mobileDataToggle"),localDataTools=$(".tools"),toolsHome=localDataTools.parentElement,toolsNext=localDataTools.nextSibling;function closeMobileData(){localDataTools.classList.remove("mobile-open");toolsHome.insertBefore(localDataTools,toolsNext);mobileDataToggle.setAttribute("aria-expanded","false");mobileDataToggle.textContent="⇅ DATA & BACKUPS"}mobileDataToggle.onclick=()=>{let opening=!localDataTools.classList.contains("mobile-open");if(opening){document.body.appendChild(localDataTools);localDataTools.classList.add("mobile-open");mobileDataToggle.setAttribute("aria-expanded","true");mobileDataToggle.textContent="× CLOSE DATA MENU"}else closeMobileData()};document.addEventListener("click",e=>{if(localDataTools.classList.contains("mobile-open")&&!localDataTools.contains(e.target)&&!mobileDataToggle.contains(e.target))closeMobileData()});
